backupCommand:
$ErrorActionPreference='Stop'
$taskRoot=[IO.Path]::GetFullPath('I:/GitHub/Unity_GAS/gameplay-ability-system-for-unity')
$taskOp='NTSD-OPTIMIZATION-BATCH36-BRUTE-EXACT-CACHE-20261007'
$taskWritePaths='["Assets/NTSD/Scripts/Animation/Character/BruteForceSceneQuery.cs","Assets/NTSD/Scripts/Test/Editor/RoleAwareCollisionShadowSelfCheckTests.cs","Assets/NTSD/Scripts/Test/Editor/BattleOptimizationWindowsAiSuiteEditor.cs","docs/ai/CHANGE-LEDGER.md","docs/ai/STATE.md","docs/ai/FILE-OPERATIONS/INDEX.md","Assets/NTSD/Docs/CODEX-CURRENT-HANDOFF.md","Assets/NTSD/Docs/battle-optimization-progress-tracker.md","docs/ai/TASKS/NTSD-OPTIMIZATION-BOUNDED-AUTOGOAL-20261007.md","Assets/NTSD/Docs/android-mobile-readiness/h-07-fresh-1000-ai-certificate.md","Temp/NTSD_ProductionEntityStress.result"]' | ConvertFrom-Json
$taskPriorManifest=Get-Content -LiteralPath docs/ai/FILE-OPERATIONS/NTSD-OPTIMIZATION-BATCH35-OBSERVER-LITERAL-READINESS-20261007/before.json -Raw | ConvertFrom-Json
$taskPriorProtected=@($taskPriorManifest.protected | Where-Object {$taskWritePaths -notcontains $_.path})
$taskMismatches=@($taskPriorProtected | Where-Object { !(Test-Path -LiteralPath $_.path) -or (Get-FileHash -LiteralPath $_.path -Algorithm SHA256).Hash -ne $_.sha256 })
if($taskMismatches.Count){throw ('Protected drift: '+($taskMismatches.path -join ', '))}
$taskBeforeDir=[IO.Path]::GetFullPath((Join-Path $taskRoot ('docs/ai/FILE-OPERATIONS/'+$taskOp+'/before')))
if(!$taskBeforeDir.StartsWith($taskRoot+[IO.Path]::DirectorySeparatorChar)){throw 'Backup outside approved root'}
if(Test-Path -LiteralPath $taskBeforeDir){throw 'Fresh before directory already exists'}
New-Item -ItemType Directory -Path $taskBeforeDir | Out-Null
$taskCopies=@()
foreach($taskPath in $taskWritePaths){
 $taskAbsolute=[IO.Path]::GetFullPath((Join-Path $taskRoot $taskPath))
 if(!$taskAbsolute.StartsWith($taskRoot+[IO.Path]::DirectorySeparatorChar)){throw 'Write outside root'}
 if(!(Test-Path -LiteralPath $taskAbsolute)){throw ('Missing write target '+$taskPath)}
 $taskBackup=Join-Path $taskBeforeDir ($taskPath.Replace('/','__'))
 Copy-Item -LiteralPath $taskAbsolute -Destination $taskBackup
 $taskHash=(Get-FileHash -LiteralPath $taskAbsolute -Algorithm SHA256).Hash
 $taskBackupHash=(Get-FileHash -LiteralPath $taskBackup -Algorithm SHA256).Hash
 if($taskHash -ne $taskBackupHash){throw 'Backup mismatch'}
 $taskCopies += [pscustomobject]@{path=$taskPath;absolute=$taskAbsolute;bytes=(Get-Item -LiteralPath $taskAbsolute).Length;sha256=$taskHash;backup=$taskBackup;backupSha256=$taskBackupHash;gitStatus=@(git status --porcelain -- $taskPath)}
}
$taskProtectedPaths=@($taskPriorProtected.path)
$taskProtectedPaths += @('Assets/NTSD/Scripts/Test/Editor/BattleCentralProductionWindowSceneProbeEditor.cs','Assets/NTSD/Scripts/Test/Editor/BattleProductionCatalogReplayEditor.cs','Assets/NTSD/Docs/android-mobile-readiness/h-11-presentation-capacity-zero-gc.md')
$taskProtectedPaths += @('docs/ai/TASKS/NTSD-OPTIMIZATION-BATCH35-OBSERVER-LITERAL-READINESS-20261007.md','docs/ai/CHANGE-RECORDS/NTSD-OPT-H11-OBSERVER-LITERAL-READINESS-035.md')
$taskProtectedPaths += @(rg --files docs/ai/FILE-OPERATIONS/NTSD-OPTIMIZATION-BATCH35-OBSERVER-LITERAL-READINESS-20261007 artifacts/diagnostics/NTSD-OPTIMIZATION-BATCH35-OBSERVER-LITERAL-READINESS-20261007 | ForEach-Object {$_.Replace('\','/')})
$taskProtected=@($taskProtectedPaths | Sort-Object -Unique | Where-Object {$taskWritePaths -notcontains $_} | ForEach-Object { [pscustomobject]@{path=$_;sha256=(Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash}})
[pscustomobject]@{operationId=$taskOp;observed=(Get-Date).ToString('o');head=(git rev-parse HEAD);branch=(git branch --show-current);before=$taskCopies;protected=$taskProtected;gitStatus=@(git status --short --branch);menuSceneSha=(Get-FileHash -LiteralPath Assets/NTSD/Scene/NTSD_Menu.unity -Algorithm SHA256).Hash;battleSceneSha=(Get-FileHash -LiteralPath Assets/NTSD/Scene/NTSD_Battle.unity -Algorithm SHA256).Hash;sharedRequestAbsent=!(Test-Path -LiteralPath Temp/NTSD_ProductionEntityStress.request.json);editorPid=(Get-Process -Id 19040).Id} | ConvertTo-Json -Depth 5 -Compress
